/// <reference types="node" />

import { Writable } from "stream";

export interface SignaleOptions {
    stream?: NodeJS.WritableStream;
    types?: {
        [key: string]: SignaleConfig;
    };
    scope?: string | string[];
    interactive?: boolean;
    disabled?: boolean;
    logLevel?: "info" | "debug" | "warn" | "error" | "fatal" | "trace";
}

export interface SignaleConfig {
    badge?: string;
    color?: string;
    label?: string;
    logLevel?: "info" | "debug" | "warn" | "error" | "fatal" | "trace";
}

export class Signale {
    constructor(options?: SignaleOptions);
    await(message: string, ...args: any[]): void;
    complete(message: string, ...args: any[]): void;
    debug(message: string, ...args: any[]): void;
    error(message: string, ...args: any[]): void;
    fatal(message: string, ...args: any[]): void;
    fav(message: string, ...args: any[]): void;
    info(message: string, ...args: any[]): void;
    note(message: string, ...args: any[]): void;
    pause(message: string, ...args: any[]): void;
    pending(message: string, ...args: any[]): void;
    star(message: string, ...args: any[]): void;
    start(message: string, ...args: any[]): void;
    success(message: string, ...args: any[]): void;
    wait(message: string, ...args: any[]): void;
    warn(message: string, ...args: any[]): void;
    watch(message: string, ...args: any[]): void;
    scope(...name: string[]): Signale;
    config(config: SignaleConfig): void;
}

export const SignaleInstance: Signale;
export default SignaleInstance;